class Box {
    static Box instance = new Box();
    int n = 0;
    static Box get() { return instance; }
    void add() { n++; }
}
class Main {
    public static void main(String[] args) {
        Box a = Box.get(), b = Box.get();
        a.add(); b.add(); a.add();
        System.out.print(b.n);
    }
}

